import{_ as d,C as i,c as r,o as t,a2 as a,b as n,w as s,a as c,G as l,a3 as p}from"./chunks/framework.DkPtUiZm.js";const f=JSON.parse('{"title":"Source unique des composants","description":"","frontmatter":{},"headers":[],"relativePath":"fondations/source-unique.md","filePath":"fondations/source-unique.md","lastUpdated":1790233006000}'),u={name:"fondations/source-unique.md"};function h(m,e,g,k,b,F){const o=i("Mermaid");return t(),r("div",null,[e[1]||(e[1]=a('<h1 id="source-unique-des-composants" tabindex="-1">Source unique des composants <a class="header-anchor" href="#source-unique-des-composants" aria-label="Permalink to &quot;Source unique des composants&quot;">​</a></h1><h2 id="decision" tabindex="-1">Décision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Décision&quot;">​</a></h2><p><code>@sia-ui/react-web</code> est la <strong>source</strong> des composants web. Le registre installable n&#39;est plus une implémentation concurrente : il devient une <strong>projection</strong> de <code>react-web</code>, produite au build.</p><p>Jusqu&#39;ici le dépôt contenait deux implémentations web sans lien entre elles :</p><ul><li><code>packages/registry/templates/</code> — 88 composants copiés chez l&#39;utilisateur, sans dépendance, avec leur propre <code>cn</code>, <code>formatDate</code> et <code>formatCurrency</code>, et un unique fichier CSS. Aucun n&#39;importe <code>@sia-ui/*</code>.</li><li><code>packages/react-web/</code> — composants distribués comme package, avec un CSS par composant.</li></ul><p>Maintenir les deux revient à écrire chaque composant deux fois. Et le registre ne mène nulle part côté mobile : on ne copie pas un <code>&lt;span&gt;</code> dans une <code>&lt;View&gt;</code>.</p><h2 id="architecture-visee" tabindex="-1">Architecture visée <a class="header-anchor" href="#architecture-visee" aria-label="Permalink to &quot;Architecture visée&quot;">​</a></h2>',7)),(t(),n(p,null,{default:s(()=>[l(o,{id:"mermaid-30",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%40sia-ui%2Ftokens%3Cbr%2F%3Evocabulaire%22%5D%20--%3E%20H%5B%22%40sia-ui%2Fheadless%3Cbr%2F%3Ecomportement%22%5D%0A%20%20H%20--%3E%20W%5B%22%40sia-ui%2Freact-web%3Cbr%2F%3Eimpl%C3%A9mentation%20DOM%22%5D%0A%20%20H%20--%3E%20N%5B%22%40sia-ui%2Freact-native%3Cbr%2F%3Epr%C3%A9vu%22%5D%0A%20%20T%20--%3E%20W%0A%20%20T%20--%3E%20N%0A%20%20W%20--%3E%20P%5B%22Projection%20au%20build%22%5D%0A%20%20P%20--%3E%20R%5B%22%40sia-ui%2Fregistry%3Cbr%2F%3Etemplates%20copiables%22%5D%0A%20%20W%20--%3E%20K%5B%22Package%20npm%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>Un composant n&#39;est écrit qu&#39;une fois, dans <code>react-web</code>. Il sort par deux canaux :</p><ul><li><strong>package</strong> — <code>pnpm add @sia-ui/react-web</code>, mis à jour par semver;</li><li><strong>registre</strong> — <code>sia-ui add badge</code>, copié chez l&#39;utilisateur qui en devient propriétaire.</li></ul><h3 id="ce-que-les-deux-plateformes-partagent-—-et-ce-qu-elles-ne-partagent-pas" tabindex="-1">Ce que les deux plateformes partagent — et ce qu&#39;elles ne partagent pas <a class="header-anchor" href="#ce-que-les-deux-plateformes-partagent-—-et-ce-qu-elles-ne-partagent-pas" aria-label="Permalink to &quot;Ce que les deux plateformes partagent — et ce qu&#39;elles ne partagent pas&quot;">​</a></h3><p>Il serait tentant de placer un contrat de props par composant dans un paquet commun, que chaque implémentation étendrait. <strong>Une forme de props ne traverse pas les plateformes</strong> : le web étend <code>HTMLAttributes</code> et prend <code>className</code>, le natif étend <code>ViewProps</code> et prend <code>style</code>; un tooltip web se place avec <code>position: fixed</code>, un tooltip natif avec un calque.</p><p>Chaque composant déclare donc ses props chez lui, comme le fait shadcn, et comme l&#39;exige le canal de copie : un contrat importé obligerait à installer un paquet pour obtenir un type.</p><p>Ce qui se partage réellement :</p><table tabindex="0"><thead><tr><th>Quoi</th><th>Où</th><th>Pourquoi</th></tr></thead><tbody><tr><td>Le vocabulaire — ton, taille, variante</td><td><code>@sia-ui/tokens</code></td><td>22 composants s&#39;en servent, le natif s&#39;en servira</td></tr><tr><td>Le comportement — machines à états, placement, calculs</td><td><code>@sia-ui/headless</code></td><td>identique des deux côtés, c&#39;est le vrai partage</td></tr><tr><td>Le client HTTP</td><td><code>@sia-ui/api</code></td><td>aucun rapport avec le rendu</td></tr><tr><td>Le contrat de formulaire</td><td><code>@sia-ui/headless</code></td><td>aucun rapport avec le rendu</td></tr><tr><td>La forme des props</td><td>nulle part</td><td>elle est propre à chaque plateforme</td></tr></tbody></table><h2 id="etat-actuel" tabindex="-1">État actuel <a class="header-anchor" href="#etat-actuel" aria-label="Permalink to &quot;État actuel&quot;">​</a></h2><p><code>@sia-ui/react-web</code> existe désormais comme package du workspace : il est installé, typé, construit et couvert par la CI. Il exporte neuf composants.</p><table tabindex="0"><thead><tr><th>Composant</th><th>État</th></tr></thead><tbody><tr><td><code>Badge</code></td><td>exporté</td></tr><tr><td><code>Divider</code></td><td>exporté</td></tr><tr><td><code>Label</code></td><td>exporté</td></tr><tr><td><code>Skeleton</code></td><td>exporté</td></tr><tr><td><code>Switch</code></td><td>exporté</td></tr><tr><td><code>Text</code></td><td>exporté</td></tr><tr><td><code>Drawer</code></td><td>exporté</td></tr><tr><td><code>Slider</code></td><td>exporté</td></tr><tr><td><code>Tooltip</code></td><td>exporté</td></tr><tr><td><code>DateTimePicker</code></td><td>attend <code>Calendar</code>, <code>Input</code> et <code>Timer</code></td></tr><tr><td><code>Form</code></td><td>attend <code>Button</code>; dépend de <code>react-hook-form</code> et <code>@hookform/resolvers/zod</code></td></tr><tr><td><code>Field</code></td><td>pas d&#39;implémentation, seulement un <code>styles.css</code> et une story</td></tr></tbody></table><p><code>DateTimePicker</code>, <code>Form</code> et <code>Field</code> restent exclus de <code>src/index.ts</code> et du <code>tsconfig.json</code> tant que leurs dépendances internes n&#39;existent pas.</p><p><code>Portal</code>, <code>usePortal</code> et <code>useOutsideClick</code> ne vivent pas ici mais dans <code>@sia-ui/react</code> : ce sont des primitives de runtime, utiles à une application comme à ce package. De même, <code>cn</code> vient de <code>@sia-ui/utils</code>. Un composant ne réimplémente jamais ce qu&#39;une couche inférieure expose déjà.</p><h3 id="cas-de-form-et-field" tabindex="-1">Cas de <code>Form</code> et <code>Field</code> <a class="header-anchor" href="#cas-de-form-et-field" aria-label="Permalink to &quot;Cas de `Form` et `Field`&quot;">​</a></h3><p>Ces deux composants importent <code>react-hook-form</code> et <code>@hookform/resolvers/zod</code>. Le parti pris du projet est de <strong>se brancher</strong> sur ces librairies, pas d&#39;en dépendre : <code>Field</code> doit rester entièrement contrôlé — <code>name</code>, <code>value</code>, <code>onChange</code>, <code>onBlur</code>, <code>error</code>, <code>ref</code> — et l&#39;adaptateur vers <code>react-hook-form</code> doit vivre à côté, optionnel. À reprendre avant de les réintégrer.</p><h2 id="migration" tabindex="-1">Migration <a class="header-anchor" href="#migration" aria-label="Permalink to &quot;Migration&quot;">​</a></h2><p>L&#39;ordre de travail est mécanique, composant par composant :</p><ol><li>écrire le contrat dans <code>packages/core/src/&lt;composant&gt;.ts</code> s&#39;il n&#39;existe pas, et l&#39;exporter depuis <code>src/index.ts</code>;</li><li>porter le template du registre vers <code>packages/react-web/src/components/</code>, en typant les props sur le contrat;</li><li>extraire ses règles de <code>templates/styles/sia-ui.css</code> vers un <code>styles.css</code> propre au composant;</li><li>exporter le composant depuis <code>react-web/src/index.ts</code> et ajouter sa story;</li><li>une fois la projection en place, supprimer le template manuel du registre.</li></ol><p>Tant que la projection n&#39;existe pas, les deux implémentations coexistent. Les stories de <code>react-web</code> sont préfixées <code>Package · react-web/</code> pour éviter les collisions d&#39;identifiants avec celles du registre.</p><h2 id="distribution-pas-de-projection" tabindex="-1">Distribution : pas de projection <a class="header-anchor" href="#distribution-pas-de-projection" aria-label="Permalink to &quot;Distribution : pas de projection&quot;">​</a></h2><p>Le registre a d&#39;abord été pensé sans aucune dépendance, ce qui imposait de générer les templates : inliner le vocabulaire de <code>@sia-ui/tokens</code>, le runtime de <code>@sia-ui/react</code>, et réécrire chaque import. Un générateur a été écrit et fonctionnait — la projection compilait avec <code>&quot;paths&quot;: {}</code>, sans qu&#39;aucun <code>@sia-ui/*</code> soit résolvable.</p><p>Il a été <strong>abandonné</strong>. Cette contrainte n&#39;était pas nécessaire : shadcn lui-même ne la respecte pas, son <code>button.tsx</code> importe <code>@radix-ui/react-slot</code> et <code>class-variance-authority</code>, et <code>registry.json</code> porte depuis toujours un champ <code>dependencies</code> pour les paquets npm.</p><p>Un template a donc le droit d&#39;importer <code>@sia-ui/tokens</code>, <code>@sia-ui/utils</code>, <code>@sia-ui/headless</code> et <code>@sia-ui/react</code>. La CLI copie le fichier source tel quel et annonce les dépendances à installer. <strong>Aucun code n&#39;est généré, aucun n&#39;est dupliqué.</strong></p><h3 id="la-cli" tabindex="-1">La CLI <a class="header-anchor" href="#la-cli" aria-label="Permalink to &quot;La CLI&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sia-ui</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">              écrit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sia-ui.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> et</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> la</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feuille</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> de</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> style</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sia-ui</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">              liste</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> les</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> entrées,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> marquées</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [pkg] quand elles viennent du package</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sia-ui</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nom..</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      installe,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> avec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ses</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dépendances</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> de</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registre</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sia-ui</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">no</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --overwrite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   écrase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> une</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> copie</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> existante</span></span></code></pre></div><p>Elle lit désormais <code>sia-ui.json</code> — <code>components</code>, <code>lib</code>, <code>styles</code> — au lieu d&#39;écrire en dur dans <code>src/</code>, et affiche les paquets npm à installer :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add  app/ui/Label/index.tsx</span></span>\n<span class="line"><span>add  app/ui/Label/styles.css</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>À installer :</span></span>\n<span class="line"><span>  pnpm add @sia-ui/headless @sia-ui/react @sia-ui/tokens @sia-ui/utils</span></span></code></pre></div><p>Le fichier installé est <strong>exactement</strong> le fichier source de <code>react-web</code>, octet pour octet. C&#39;est ce que permet le droit d&#39;importer <code>@sia-ui/*</code>, et c&#39;est ce qui garantit qu&#39;il n&#39;y a plus qu&#39;une implémentation.</p><h3 id="le-schema-des-entrees" tabindex="-1">Le schéma des entrées <a class="header-anchor" href="#le-schema-des-entrees" aria-label="Permalink to &quot;Le schéma des entrées&quot;">​</a></h3><p>Chaque entrée porte maintenant :</p><table tabindex="0"><thead><tr><th>Champ</th><th>Rôle</th></tr></thead><tbody><tr><td><code>version</code></td><td>version de l&#39;entrée, indépendante de celle du package</td></tr><tr><td><code>status</code></td><td><code>experimental</code>, <code>stable</code>, <code>deprecated</code> ou <code>removed</code></td></tr><tr><td><code>source</code></td><td><code>package</code> (copié depuis <code>react-web</code>) ou <code>template</code> (écrit à la main)</td></tr><tr><td><code>dependencies</code></td><td>paquets npm annoncés par la CLI, jamais installés d&#39;office</td></tr></tbody></table><p>La CLI refuse une entrée <code>removed</code>, prévient sur une entrée <code>deprecated</code> et affiche son remplacement.</p><h3 id="pourquoi-0-1-0-et-pas-1-0-0" tabindex="-1">Pourquoi <code>0.1.0</code> et pas <code>1.0.0</code> <a class="header-anchor" href="#pourquoi-0-1-0-et-pas-1-0-0" aria-label="Permalink to &quot;Pourquoi `0.1.0` et pas `1.0.0`&quot;">​</a></h3><p>Toutes les entrées et tous les paquets sont à <code>0.1.0</code>. Rien n&#39;est publié : en semver, le <code>0.</code> majeur veut dire « l&#39;API n&#39;est pas figée, une rupture peut arriver en mineure ».</p><p>C&#39;est ce qu&#39;il faut ici, parce que plusieurs décisions sont encore ouvertes et qu&#39;elles seront chacune une rupture :</p><ul><li>les sept composants qui existent des deux côtés, à arbitrer;</li><li>le sort de <code>ConfigProvider</code>;</li><li><code>Field</code> et <code>Form</code>, à détacher de <code>react-hook-form</code>;</li><li>les 85 entrées qui passeront de <code>template</code> à <code>package</code>.</li></ul><p>Passer en <code>1.0.0</code> maintenant reviendrait à s&#39;engager sur une API qu&#39;on sait devoir changer, et à brûler <code>2.0.0</code>, <code>3.0.0</code>, <code>4.0.0</code> sur des décisions internes que personne n&#39;a encore consommées.</p><p><code>1.0.0</code> est le premier engagement public : il vient en phase 7, quand la migration est finie et les arbitrages rendus.</p><h2 id="migration-faite" tabindex="-1">Migration : faite <a class="header-anchor" href="#migration-faite" aria-label="Permalink to &quot;Migration : faite&quot;">​</a></h2><p>Les 88 entrées historiques ont rejoint <code>packages/react-web/src/components/</code>. <code>packages/registry/templates/</code> n&#39;existe plus.</p><table tabindex="0"><thead><tr><th></th><th>Avant</th><th>Après</th></tr></thead><tbody><tr><td>Entrées du registre</td><td>88 <code>template</code> + 2 <code>package</code></td><td><strong>87, toutes <code>package</code></strong></td></tr><tr><td>Composants dans <code>react-web</code></td><td>9</td><td><strong>88</strong></td></tr><tr><td>Feuille de style</td><td>un fichier de 202 lignes</td><td>68 feuilles par composant + une commune</td></tr><tr><td>Fichiers copiés pour <code>crud-page</code></td><td>12, dont 3 de bibliothèque</td><td>9 composants, 0 bibliothèque</td></tr></tbody></table><h3 id="deplacer-par-etapes-n-a-pas-servi" tabindex="-1">Déplacer par étapes n&#39;a pas servi <a class="header-anchor" href="#deplacer-par-etapes-n-a-pas-servi" aria-label="Permalink to &quot;Déplacer par étapes n&#39;a pas servi&quot;">​</a></h3><p>L&#39;ordre imposé par le graphe de dépendances ne valait que pour un déplacement composant par composant. En les déplaçant <strong>tous ensemble</strong>, les imports voisins se résolvent entre eux à l&#39;arrivée : l&#39;ordre n&#39;a plus d&#39;objet.</p><h3 id="le-decoupage-de-la-feuille-de-style" tabindex="-1">Le découpage de la feuille de style <a class="header-anchor" href="#le-decoupage-de-la-feuille-de-style" aria-label="Permalink to &quot;Le découpage de la feuille de style&quot;">​</a></h3><p>609 règles, réparties automatiquement : une règle part avec un composant si <strong>lui seul</strong> peut la revendiquer, d&#39;après les classes que son fichier cite. Sinon elle reste dans <code>src/styles/shared.css</code> — variables de thème, animations partagées, ajustements responsives transverses.</p><p>571 règles ont trouvé un composant, 146 sont communes. Les 38 restantes appartenaient à <code>slider</code>, <code>tooltip</code> et <code>drawer</code>, dont la version de <code>react-web</code> a été retenue : leur CSS est remplacé, pas perdu.</p><p>L&#39;invariant a été vérifié : <strong>aucune règle du registre n&#39;a disparu sans arbitrage explicite.</strong></p><h3 id="les-arbitrages" tabindex="-1">Les arbitrages <a class="header-anchor" href="#les-arbitrages" aria-label="Permalink to &quot;Les arbitrages&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Composant</th><th>Retenu</th><th>Pourquoi</th></tr></thead><tbody><tr><td><code>slider</code>, <code>tooltip</code>, <code>drawer</code></td><td><code>react-web</code></td><td>déjà câblés sur <code>@sia-ui/headless</code></td></tr><tr><td><code>badge</code>, <code>divider</code>, <code>skeleton</code>, <code>switch</code></td><td>registre</td><td>versions plus riches — tons, chargement</td></tr><tr><td><code>field</code>, <code>date-time-picker</code></td><td>registre</td><td>les brouillons de <code>react-web</code> étaient incomplets</td></tr><tr><td><code>text</code></td><td>supprimé</td><td>doublon de <code>typography</code>, plus complet</td></tr></tbody></table><p>Les fonctions que le registre avait en plus ont été récupérées plutôt que perdues : <code>minDistance</code> est descendu dans <code>useSliderState</code>, <code>showValue</code>, <code>formatValue</code>, <code>startLabel</code> et <code>endLabel</code> dans le contrat <code>ISliderProps</code>, et <code>TooltipProps</code> reste exporté comme alias avec un <code>content</code> facultatif.</p><h3 id="ce-qui-reste-dehors" tabindex="-1">Ce qui reste dehors <a class="header-anchor" href="#ce-qui-reste-dehors" aria-label="Permalink to &quot;Ce qui reste dehors&quot;">​</a></h3><p><code>Form</code> est exclu du barrel et du typage : il importe <code>react-hook-form</code> et <code>@hookform/resolvers/zod</code> en dur, ce que la règle du projet interdit. Il attend d&#39;être repris en composant contrôlé, avec l&#39;adaptateur à côté.</p><h2 id="regle" tabindex="-1">Règle <a class="header-anchor" href="#regle" aria-label="Permalink to &quot;Règle&quot;">​</a></h2><p>Un composant web ne s&#39;écrit plus dans <code>packages/registry/templates/</code>. Une contribution qui ajoute un template sans passer par <code>react-web</code> est à refuser.</p>',53))])}const v=d(u,[["render",h]]);export{f as __pageData,v as default};
